import assert from 'node:assert/strict';
import {createGardenState,restoreGardenState,stepGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {GARDEN as C,gardenPlatforms,GARDEN_ENEMIES} from '../../../../src/js/garden/GardenLevel.js';
const ready=d=>{const s=createGardenState(d);s.stage='RUNNING';return s;};
for(const difficulty of ['NORMAL','EASY']){
 const s=ready(difficulty);const p=s.player;stepGarden(s,{jump:true},1/60,difficulty);assert.ok(p.vy<0);const impulse=p.vy;
 for(let i=0;i<90;i++)stepGarden(s,{jump:true},1/60,difficulty);assert.ok(p.onGround,'Segurar não repete o salto');assert.equal(p.vy,0);assert.ok(impulse<-650);
 const coyote=ready(difficulty);Object.assign(coyote.player,{x:1458,y:590,onGround:false,support:null});coyote.coyote=.07;stepGarden(coyote,{jump:true},1/120,difficulty);assert.ok(coyote.player.vy<0,'Tolerância após sair da borda');
 const buffered=ready(difficulty);Object.assign(buffered.player,{y:575,vy:300,onGround:false,support:null});for(let i=0;i<14;i++)stepGarden(buffered,{jump:true},1/120,difficulty);assert.ok(buffered.player.vy<0,'Pulo antecipado dispara ao pousar');
 const stomp=ready(difficulty);const e=stomp.enemies[0];Object.assign(stomp.player,{x:e.x,y:e.y-e.h-2,vy:300,onGround:false,support:null});const hp=stomp.hp;const events=stepGarden(stomp,{x:0},1/60,difficulty);assert.ok(!e.alive&&stomp.player.vy<0&&stomp.defeated===1,'Pisão derrota e rebate');assert.equal(stomp.hp,hp);assert.ok(events.some(e=>e.type==='stomp'));
 const side=ready(difficulty);Object.assign(side.player,{x:side.enemies[0].x,y:590});stepGarden(side,{},1/60,difficulty);assert.equal(side.hp,(difficulty==='EASY'?6:3)-1,'Contato lateral tira um coração');const after=side.hp;for(let i=0;i<8;i++)stepGarden(side,{},1/60,difficulty);assert.equal(side.hp,after,'Imunidade evita dano repetido');
 const fall=ready(difficulty);fall.player.y=1000;stepGarden(fall,{},1/60,difficulty);assert.equal(fall.player.x,120);assert.equal(fall.hp,(difficulty==='EASY'?6:3)-1);fall.hp=1;fall.player.y=1000;stepGarden(fall,{},1/60,difficulty);assert.equal(fall.stage,'GAME_OVER');
 const win=ready(difficulty);win.player.x=C.goal;stepGarden(win,{},1/60,difficulty);assert.equal(win.stage,'COMPLETE');const x=win.player.x;for(let i=0;i<120;i++)stepGarden(win,{x:1,jump:true},1/60,difficulty);assert.equal(win.player.x,x,'Chegada mantém menina sob árvore');
 const onWheel=ready(difficulty),a=gardenPlatforms(0).find(p=>p.id==='roda-0');Object.assign(onWheel.player,{x:a.x+72,y:a.y,onGround:true,support:a.id});stepGarden(onWheel,{},1/120,difficulty);const b=gardenPlatforms(onWheel.time).find(p=>p.id===a.id);assert.ok(Math.abs(onWheel.player.y-b.y)<.01&&onWheel.player.onGround,'Roda transporta os pés sem escorregar');
 for(const state of [s,stomp,side,fall,win,onWheel]){const saved=JSON.parse(JSON.stringify(state)),restored=restoreGardenState(saved,difficulty);assert.equal(restored.stage,saved.stage);assert.equal(restored.player.x,saved.player.x);assert.equal(restored.defeated,saved.enemies.filter(e=>!e.alive).length);}
}
assert.throws(()=>restoreGardenState({version:1,stage:'RUNNING'}),TypeError);
assert.throws(()=>{const s=ready('NORMAL');s.player.x=Infinity;restoreGardenState(s);},TypeError);
console.log('APROVADO: pulo, tolerância de borda, buffer, pisão, contato lateral, imunidade, água/queda, derrota, chegada, roda móvel e save válido/inválido nas duas dificuldades.');
